use std::collections::HashSet;

/// Removes duplicates from the input vector `nums`, returning a new vector with no duplicates.
/// The returned vector contains the same set of elements as `nums`, but with no repeated values.
///
/// Properties:
/// 1) The output contains no duplicates.
/// 2) The output's set of elements equals the input's set of elements.
///
/// The order of elements in the output preserves the first occurrence of each unique value.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for &num in &nums {
        if seen.insert(num) {
            // Insert returns true if num was not present before
            result.push(num);
        }
    }

    result
}

